package com.oguzguven.portfolio.contact;
public record ContactResponse(String eyebrow,String kicker,String titlePrefix,String titleHighlight,String description,String githubUrl,String githubLabel,String linkedinUrl,String linkedinLabel,String email,String emailLabel,String formSubject,String namePlaceholder,String emailPlaceholder,String messagePlaceholder,String submitText,String successMessage,String errorMessage,String footerName,String footerRole,String footerLocation,String footerCopyright){static ContactResponse from(Contact c){return new ContactResponse(c.getEyebrow(),c.getKicker(),c.getTitlePrefix(),c.getTitleHighlight(),c.getDescription(),c.getGithubUrl(),c.getGithubLabel(),c.getLinkedinUrl(),c.getLinkedinLabel(),c.getEmail(),c.getEmailLabel(),c.getFormSubject(),c.getNamePlaceholder(),c.getEmailPlaceholder(),c.getMessagePlaceholder(),c.getSubmitText(),c.getSuccessMessage(),c.getErrorMessage(),c.getFooterName(),c.getFooterRole(),c.getFooterLocation(),c.getFooterCopyright());}}
